 dict(kind="table", head="आयु संरचना: तीन समूह", eq="किस उम्र के कितने लोग (2011)",
      rows=[["समूह", "उम्र", "हिस्सा", "स्थिति"], ["बच्चे", "0–14 साल", "~31%", "आश्रित — खाना, कपड़ा, पढ़ाई, इलाज चाहिए"], ["वयस्क (कार्यशील)", "15–59 साल", "~60%", "कमाने वाले — देश की ताक़त"], ["वृद्ध", "60 साल से ऊपर", "~9%", "आश्रित (कुछ काम करते भी हैं)"]],
      say="अब जनसंख्या के गुण। पहला, आयु संरचना, यानी किस उम्र के कितने लोग हैं। तीन समूह हैं। बच्चे, चौदह साल तक, लगभग इकतीस प्रतिशत। ये आश्रित हैं, इन्हें खाना, कपड़ा, पढ़ाई और इलाज चाहिए। वयस्क, पंद्रह से उनसठ साल, लगभग साठ प्रतिशत। ये कमाने वाले हैं, देश की असली ताक़त। और वृद्ध, साठ साल से ऊपर, लगभग नौ प्रतिशत। भारत में कमाने की उम्र वाले लोग बहुत हैं, और देश की औसत उम्र सिर्फ़ लगभग अट्ठाईस-उनतीस साल है। यानी भारत एक युवा देश है। अगर इन युवाओं को अच्छी शिक्षा और रोज़गार मिले, तो ये देश की सबसे बड़ी ताक़त बन सकते हैं।"),

 dict(kind="eq", icon="⚖️", head="लिंग अनुपात", words="हर 1000 पुरुषों पर महिलाओं की संख्या", eq="भारत (2011): 943 · केरल: 1084 (सबसे अच्छा) · हरियाणा: 879 · बिहार: 918",
      note="1000 से कम क्यों? बेटियों से भेदभाव, भ्रूण-हत्या (अपराध!), कम देखभाल",
      say="दूसरा गुण, लिंग अनुपात, यानी हर एक हज़ार पुरुषों पर महिलाओं की संख्या। दो हज़ार ग्यारह में भारत का लिंग अनुपात नौ सौ तैंतालीस था। यानी हर हज़ार पुरुषों पर, सत्तावन महिलाएँ कम। केरल में सबसे अच्छा, एक हज़ार चौरासी। हरियाणा में सबसे कम, आठ सौ उनासी। और बिहार में नौ सौ अठारह। ये हज़ार से कम क्यों है? क्योंकि समाज में बेटियों से भेदभाव होता है। जन्म से पहले ही लिंग की जाँच कराकर बेटियों को मार देना, जो क़ानूनन अपराध है, और बेटियों के खाने, पढ़ाई और इलाज पर कम ध्यान। ये हमारे समाज पर एक धब्बा है, जिसे हमें मिलकर मिटाना है।"),

 dict(kind="eq", icon="📚", head="साक्षरता दर", words="साक्षर = 7 साल या उससे बड़ा व्यक्ति, जो किसी भाषा को समझकर पढ़-लिख सके", eq="भारत (2011): 73% (पुरुष 80.9%, महिला 64.6%) · केरल ~94% · बिहार 61.8% (सबसे कम)",
      note="बिहार: पुरुष ~71%, महिला ~51% — पर 2001 से 2011 में सबसे तेज़ सुधार!",
      say="तीसरा गुण, साक्षरता। जनगणना के अनुसार, सात साल या उससे बड़ा जो व्यक्ति, किसी भी भाषा को समझकर पढ़ और लिख सके, वो साक्षर है। दो हज़ार ग्यारह में, भारत की साक्षरता दर तिहत्तर प्रतिशत थी। पुरुषों में लगभग इक्यासी, और महिलाओं में लगभग पैंसठ प्रतिशत। केरल में सबसे ज़्यादा, लगभग चौरानवे प्रतिशत। और दुख की बात, बिहार में सबसे कम, लगभग बासठ प्रतिशत, जिसमें महिलाओं की साक्षरता सिर्फ़ इक्यावन प्रतिशत के आसपास। पर अच्छी बात ये है कि उस दशक में, बिहार में साक्षरता सबसे तेज़ी से बढ़ी। और बच्चों, आप सब स्कूल आ रहे हैं, यानी ये तस्वीर बदल रही है।"),

 dict(kind="table", head="व्यावसायिक संरचना: कौन क्या काम करता है?", eq="काम के तीन क्षेत्र",
      rows=[["क्षेत्र", "काम", "उदाहरण"], ["प्राथमिक", "प्रकृति से सीधे जुड़े", "खेती, पशुपालन, मछली पकड़ना, खनन, वानिकी"], ["द्वितीयक", "कच्चे माल से सामान बनाना", "कारख़ाने, भवन-निर्माण"], ["तृतीयक", "सेवाएँ", "परिवहन, संचार, बैंक, व्यापार, शिक्षक, डॉक्टर"]],
      say="चौथा गुण, व्यावसायिक संरचना, यानी लोग क्या काम करते हैं। काम के तीन क्षेत्र हैं। प्राथमिक, जो प्रकृति से सीधे जुड़े हैं, जैसे खेती, पशुपालन, मछली पकड़ना और खनन। द्वितीयक, जिसमें कच्चे माल से सामान बनाया जाता है, जैसे कारख़ाने और भवन-निर्माण। और तृतीयक, यानी सेवाएँ, जैसे परिवहन, बैंक, व्यापार, शिक्षक और डॉक्टर। विकसित देशों में ज़्यादातर लोग द्वितीयक और तृतीयक क्षेत्र में काम करते हैं। भारत में अब भी लगभग आधे कामगार खेती में लगे हैं, और बिहार में तो इससे भी ज़्यादा। पर धीरे-धीरे लोग उद्योग और सेवाओं की ओर बढ़ रहे हैं।"),

 dict(kind="list", icon="🏥", head="स्वास्थ्य",
      points=["मृत्यु दर: 1951 में 25 प्रति हज़ार → 2011 में ~7", "औसत आयु (जीवन प्रत्याशा): 1951 में ~37 साल → 2012 में ~67 साल → अब ~70", "कारण: टीकाकरण, अस्पताल, संक्रामक रोगों पर क़ाबू", "चुनौतियाँ: कुपोषण (ख़ासकर बच्चे और माताएँ), साफ़ पानी, शौचालय — बिहार में अब भी बड़ी चुनौती"],
      say="पाँचवाँ गुण, स्वास्थ्य। आज़ादी के बाद स्वास्थ्य में बड़ा सुधार हुआ है। मृत्यु दर, उन्नीस सौ इक्यावन के पच्चीस प्रति हज़ार से घटकर, लगभग सात रह गई। और औसत आयु, उन्नीस सौ इक्यावन में सिर्फ़ लगभग सैंतीस साल थी, जो अब बढ़कर लगभग सत्तर साल हो गई है। ये टीकाकरण, अस्पतालों, और संक्रामक रोगों पर क़ाबू से हुआ। पर चुनौतियाँ बाक़ी हैं। बहुत से बच्चे और माताएँ कुपोषण की शिकार हैं, और हर घर तक साफ़ पानी और शौचालय पहुँचाना अब भी बड़ा काम है। बिहार में ये चुनौतियाँ और बड़ी हैं।"),

 dict(kind="content", icon="🧑‍🎓", head="किशोर जनसंख्या: आप सब!",
      points=["किशोर: 10 से 19 साल · भारत की आबादी का लगभग पाँचवाँ हिस्सा", "देश का भविष्य, सबसे क़ीमती संसाधन", "पर: बहुतों को पूरा पोषण नहीं — ख़ासकर लड़कियों में ख़ून की कमी (एनीमिया)", "उपाय: हरी सब्ज़ी, दाल, गुड़-चना · आयरन की गोली (स्कूल में मिलती है) · पढ़ाई जारी रखो, बाल-विवाह नहीं"],
      say="अब एक ख़ास समूह, जिसमें आप सब हैं, किशोर जनसंख्या, यानी दस से उन्नीस साल के बच्चे। ये भारत की आबादी का लगभग पाँचवाँ हिस्सा हैं, और देश का भविष्य। पर इनमें से बहुतों को पूरा पोषण नहीं मिलता। ख़ासकर बहुत सी किशोरियों में ख़ून की कमी, यानी एनीमिया होता है, जिससे थकान और कमज़ोरी रहती है। उपाय, हरी पत्तेदार सब्ज़ियाँ, दाल, गुड़ और चना खाइए। स्कूल में जो आयरन की नीली गोली मिलती है, उसे ज़रूर खाइए। पढ़ाई बीच में मत छोड़िए। और बाल-विवाह को साफ़ मना कीजिए, ये क़ानूनन अपराध भी है।"),

 dict(kind="list", icon="📜", head="राष्ट्रीय जनसंख्या नीति",
      points=["1952: परिवार नियोजन कार्यक्रम — ऐसा करने वाला दुनिया का पहला देश!", "राष्ट्रीय जनसंख्या नीति 2000:", "14 साल तक मुफ़्त और अनिवार्य शिक्षा · शिशु मृत्यु दर 30 प्रति हज़ार से कम", "सभी बच्चों का टीकाकरण · लड़कियों की शादी की उम्र बढ़ाना · परिवार कल्याण को जन-आंदोलन बनाना"],
      say="बढ़ती आबादी को देखते हुए, भारत सरकार ने उन्नीस सौ बावन में ही परिवार नियोजन कार्यक्रम शुरू कर दिया था, ऐसा करने वाला भारत दुनिया का पहला देश था। फिर सन दो हज़ार में, राष्ट्रीय जनसंख्या नीति बनी। इसके मुख्य लक्ष्य हैं, चौदह साल तक के सभी बच्चों को मुफ़्त और अनिवार्य शिक्षा। शिशु मृत्यु दर को तीस प्रति हज़ार से नीचे लाना। सभी बच्चों का टीकाकरण। लड़कियों की शादी की उम्र बढ़ाने को बढ़ावा। और परिवार कल्याण को, लोगों का अपना आंदोलन बनाना। इस नीति में किशोरों की ज़रूरतों, जैसे पोषण और शिक्षा, पर भी ख़ास ध्यान दिया गया है।"),

 dict(kind="compare", icon="⚖️", head="जनसंख्या: बोझ या ताक़त?",
      left={"icon": "😟", "t": "अगर लोग अनपढ़, बीमार, बेरोज़गार", "d": "संसाधनों पर दबाव<br>ग़रीबी, भीड़, बेरोज़गारी"},
      right={"icon": "💪", "t": "अगर लोग शिक्षित, स्वस्थ, हुनरमंद", "d": "मानव संसाधन = मानव पूँजी<br>देश की सबसे बड़ी ताक़त"},
      say="तो क्या बड़ी जनसंख्या बोझ है, या ताक़त? जवाब है, ये इस पर निर्भर करता है कि लोग कैसे हैं। अगर लोग अनपढ़, बीमार और बेरोज़गार हों, तो बड़ी आबादी, संसाधनों पर दबाव बन जाती है। पर अगर वही लोग शिक्षित, स्वस्थ और हुनरमंद हों, तो वो देश की सबसे बड़ी ताक़त बन जाते हैं, जिसे मानव पूँजी कहते हैं। जापान के पास खनिज बहुत कम हैं, पर उसके शिक्षित और मेहनती लोगों ने उसे दुनिया के सबसे अमीर देशों में पहुँचा दिया।"),

 dict(kind="content", icon="📋", head="कहानी का अंत",
      points=["मास्टर जी: गिनती से पता चला — गाँव में कितने बच्चे स्कूल नहीं जाते", "पंचायत ने 'स्कूल चलो' अभियान चलाया", "सोनू ने पड़ोस की दो बहनों का दाख़िला करवाया", "मास्टर जी: हर पढ़ा-लिखा बच्चा, देश की गिनती में एक ताक़त"],
      say="जनगणना पूरी होने के बाद, मास्टर जी ने पंचायत में बताया कि गाँव में कितने बच्चे स्कूल नहीं जाते, और उनमें लड़कियाँ ज़्यादा हैं। पंचायत ने तुरंत स्कूल चलो अभियान चलाया। सोनू ने अपने पड़ोस की दो बहनों को, जो घर के काम के कारण स्कूल नहीं आती थीं, उनके माता-पिता को समझाकर दाख़िला दिलवाया। मास्टर जी ने उसकी पीठ थपथपाई, शाबाश सोनू! हर पढ़ा-लिखा बच्चा, देश की गिनती में सिर्फ़ एक संख्या नहीं, एक ताक़त है।"),

 dict(kind="list", icon="📝", head="पूरे पाठ का सार",
      points=["लोग = संसाधन · जनगणना हर 10 साल (1872, 1881, … 2011)", "2011: 121 करोड़ (दुनिया का 17.5%) · घनत्व 382 · बिहार: तीसरा बड़ा राज्य, घनत्व 1106 (सबसे ज़्यादा)", "वृद्धि: जन्म दर, मृत्यु दर, प्रवास · वृद्धि दर 1981 के बाद घटती हुई", "गुण: आयु संरचना (60% कार्यशील), लिंग अनुपात 943, साक्षरता 73% (बिहार 61.8%), व्यवसाय, स्वास्थ्य", "किशोर जनसंख्या · राष्ट्रीय जनसंख्या नीति 2000"],
      say="तो बच्चों, सार। एक, लोग ही असली संसाधन हैं, और जनगणना हर दस साल में होती है। दो, दो हज़ार ग्यारह में भारत की आबादी एक सौ इक्कीस करोड़, घनत्व तीन सौ बयासी, और बिहार का घनत्व सबसे ज़्यादा। तीन, जनसंख्या जन्म, मृत्यु और प्रवास से बदलती है। चार, जनसंख्या के गुण, आयु संरचना, लिंग अनुपात, साक्षरता, व्यवसाय और स्वास्थ्य। पाँच, किशोर जनसंख्या, और राष्ट्रीय जनसंख्या नीति।"),

